"""Generate agents/registry.yaml and agents/<name>/contract.md from one source of truth."""
import json
from pathlib import Path
A = [
 ("triage", "Intake routing", "T1 (Haiku 5.5; rules fallback)", [], "implemented", "assistant/agents/triage.py", "Classify (intent, domain, risk, complexity); route computed in code, rules may only raise risk.", "Never executes tools; never lowers risk; route not taken from model output."),
 ("model_router", "Model selection", "deterministic", [], "implemented", "assistant/router/router.py", "Tiered model ladder with retry, fallback, breaker, budgets, abstention.", "No LLM in decision path; never returns unvalidated structured output."),
 ("guardrails", "Safety (PII + injection)", "deterministic", [], "implemented", "assistant/plugins/", "Redact PII and block prompt injection before anything is logged, cached or sent to a model.", "Fail-closed; cannot be disabled by flags."),
 ("query_rewrite", "Query understanding", "T1", [], "planned", "-", "Rewrite follow-up questions into standalone queries.", "No data access."),
 ("retrieval", "Retrieval", "deterministic pipeline", ["hybrid_retrieve"], "implemented", "assistant/agent/subagents.py", "Hybrid retrieval with abstention and low-confidence flagging.", "Read-only; cannot call mutating tools."),
 ("execution", "Transactions", "T2 reasoner", ["lookup_sku", "lookup_lot", "transition_workflow"], "implemented", "assistant/agent/subagents.py", "Bounded ReAct over state-store tools; Tier-3 requests freeze for human approval.", "No RAG/web; never applies Tier-3 itself."),
 ("verification", "Grounding", "independent model (haiku-4.5)", [], "implemented", "assistant/agent/generation.py", "Claim-level fact check with literal-quote proof plus deterministic number/ID grounding; can veto.", "Never sees generator prompt; fails closed to extractive answer."),
 ("memory", "Context/memory", "deterministic", [], "partial", "assistant/agent/loop.py", "Goal anchor, observation compression, 3-turn window, verified-fact store.", "In-memory only; Postgres session_facts pending."),
 ("graphify_vault", "Token savings", "deterministic", ["graph_subgraph"], "implemented", "assistant/graphify.py + mcp_servers/graphify_server.py", "Depth<=2 pruned context from Obsidian notes.", "Read-only; depth hard-capped at 2."),
 ("eval", "Evaluation", "offline T2", [], "implemented", "assistant/eval_ragas.py + scripts/eval_ragas.py", "RAGAS-lite proxy metrics on the golden set.", "Never in the request path; proxy judge is not the official ragas package."),
 ("incident", "Ops", "T1 + rules", [], "planned", "-", "Map alerts to runbooks; propose mitigations.", "Proposes only; humans approve risky actions."),
 ("rollout_controller", "Release", "deterministic", [], "implemented", "assistant/release.py", "Canary 1/5/25/100 with auto-rollback on guardrail breach.", "In-process; no real flag service yet."),
 ("ingestion", "Data ingestion", "offline", [], "implemented", "assistant/rag/ingest.py + scripts/build_corpus.py + scripts/build_vault.py", "Chunk docs, build index, vault notes and graph.", "Versioned output; no signing yet."),
]
root = Path("agents"); root.mkdir(exist_ok=True)
reg = []
for n, feat, tier, tools, status, impl, purpose, non in A:
    d = root / n; d.mkdir(exist_ok=True)
    (d / "contract.md").write_text(f"# {n}\n\n- Feature: {feat}\n- Status: **{status}**\n- Implementation: `{impl}`\n- Model tier: {tier}\n- Tool allowlist: {tools or 'none'}\n\n## Purpose\n{purpose}\n\n## Non-goals / guardrails\n{non}\n\n## Required before 'done'\nI/O schemas, timeouts, FMEA rows, OTel spans, eval set, owner.\n")
    reg.append({"name": n, "feature": feat, "tier": tier, "tools": tools, "status": status, "implementation": impl})
(root / "registry.yaml").write_text("# generated by scripts/gen_agent_contracts.py\n" + "\n".join(f"- {json.dumps(r)}" for r in reg) + "\n")
print(len(reg), "agents;", sum(r["status"] == "implemented" for r in reg), "implemented")
